function AvatarUploader({
  initials,
  onChange,
}: {
  initials: string;
  onChange: () => void;
}) {
  const inputRef = React.useRef<HTMLInputElement>(null);
  const [preview, setPreview] = React.useState<string | null>(null);
  const [error, setError] = React.useState<string | null>(null);

  // Revoke object URLs to avoid leaking memory.
  React.useEffect(() => {
    return () => {
      if (preview) URL.revokeObjectURL(preview);
    };
  }, [preview]);

  const handleFile = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    event.target.value = "";
    if (!file) return;
    if (!file.type.startsWith("image/")) {
      setError("Please choose an image file (PNG, JPG, GIF or WebP).");
      return;
    }
    if (file.size > MAX_AVATAR_BYTES) {
      setError("That image is larger than 2 MB. Try a smaller one.");
      return;
    }
    setError(null);
    setPreview(URL.createObjectURL(file));
    onChange();
    toast.success("Photo selected", {
      description: "Save your changes to apply the new photo.",
    });
  };

  const handleRemove = () => {
    setPreview(null);
    setError(null);
    onChange();
  };

  return (
    <div className="flex flex-col gap-4 sm:flex-row sm:items-center">
      <Avatar className="size-20 shrink-0 text-xl">
        {preview && <AvatarImage src={preview} alt="Your profile photo" />}
        <AvatarFallback className="text-xl font-medium">
          {initials || "?"}
        </AvatarFallback>
      </Avatar>

      <div className="min-w-0 space-y-2">
        <p className="text-sm font-medium" id="avatar-label">
          Profile photo
        </p>
        <div className="flex flex-wrap gap-2">
          <input
            ref={inputRef}
            type="file"
            accept="image/png,image/jpeg,image/gif,image/webp"
            className="sr-only"
            onChange={handleFile}
            aria-labelledby="avatar-label"
            aria-describedby="avatar-help"
            tabIndex={-1}
          />
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={() => inputRef.current?.click()}
          >
            <Upload aria-hidden="true" />
            Upload new photo
          </Button>
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={handleRemove}
            disabled={!preview}
          >
            Remove
          </Button>
        </div>
        <p id="avatar-help" className="text-xs text-muted-foreground">
          PNG, JPG, GIF or WebP. Max size 2 MB.
        </p>
        {error && (
          <p role="alert" className="text-sm text-destructive">
            {error}
          </p>
        )}
      </div>
    </div>
  );
}

